using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _service;

    public OrderServiceTests()
    {
        _service = new OrderService();
    }

    private static List<OrderItem> CreateSampleItems(int count = 1) =>
        Enumerable.Range(1, count)
            .Select(i => new OrderItem { ProductName = $"Product {i}", Price = 10m * i, Quantity = i })
            .ToList();

    #region CreateOrder

    [TestMethod]
    public void CreateOrder_WithValidInputs_ReturnsOrderWithCorrectTotal()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "Widget", Price = 25.00m, Quantity = 2 },
            new() { ProductName = "Gadget", Price = 15.00m, Quantity = 3 },
        };

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual("cust-1", order.CustomerId);
        Assert.AreEqual(95.00m, order.Total); // 25*2 + 15*3
        Assert.IsNotNull(order.Id);
        Assert.HasCount(2, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithSingleItem_ReturnsCorrectTotal()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "Book", Price = 12.99m, Quantity = 1 },
        };

        // Act
        var order = _service.CreateOrder("cust-2", items);

        // Assert
        Assert.AreEqual(12.99m, order.Total);
        var single = Assert.ContainsSingle(order.Items);
        Assert.AreEqual("Book", single.ProductName);
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToUtcNow()
    {
        // Arrange
        var before = DateTime.UtcNow;
        var items = CreateSampleItems();

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        var after = DateTime.UtcNow;
        Assert.IsInRange(order.CreatedAt, before, after);
    }

    [TestMethod]
    public void CreateOrder_WithNullCustomerId_ThrowsArgumentNullException()
    {
        var items = CreateSampleItems();

        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _service.CreateOrder(null!, items));

        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithNullItems_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _service.CreateOrder("cust-1", null!));

        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _service.CreateOrder("cust-1", []));

        Assert.AreEqual("Cannot create an order with no items.", ex.Message);
    }

    #endregion

    #region GetOrder

    [TestMethod]
    public void GetOrder_WithExistingId_ReturnsMatchingOrder()
    {
        // Arrange
        var items = CreateSampleItems();
        var created = _service.CreateOrder("cust-1", items);

        // Act
        var retrieved = _service.GetOrder(created.Id);

        // Assert
        Assert.IsNotNull(retrieved);
        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_WithNonExistentId_ReturnsNull()
    {
        var result = _service.GetOrder("non-existent-id");

        Assert.IsNull(result);
    }

    #endregion

    #region GetOrdersByCustomer

    [TestMethod]
    public void GetOrdersByCustomer_WithMultipleOrders_ReturnsAll()
    {
        // Arrange
        _service.CreateOrder("cust-A", CreateSampleItems());
        _service.CreateOrder("cust-A", CreateSampleItems(2));
        _service.CreateOrder("cust-B", CreateSampleItems());

        // Act
        var results = _service.GetOrdersByCustomer("cust-A");

        // Assert
        Assert.HasCount(2, results);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithNoOrders_ReturnsEmptyList()
    {
        var results = _service.GetOrdersByCustomer("unknown-customer");

        Assert.IsEmpty(results);
    }

    [TestMethod]
    public void GetOrdersByCustomer_DoesNotReturnOtherCustomerOrders()
    {
        // Arrange
        var otherOrder = _service.CreateOrder("cust-B", CreateSampleItems());
        _service.CreateOrder("cust-A", CreateSampleItems());

        // Act
        var results = _service.GetOrdersByCustomer("cust-A");

        // Assert
        Assert.DoesNotContain(otherOrder, results);
    }

    #endregion

    #region DataDriven

    [TestMethod]
    [DataRow(10.00, 2, 20.00, DisplayName = "Simple multiplication")]
    [DataRow(5.50, 4, 22.00, DisplayName = "Decimal price")]
    [DataRow(99.99, 1, 99.99, DisplayName = "Single quantity")]
    public void CreateOrder_CalculatesTotalCorrectly(double price, int qty, double expectedTotal)
    {
        var items = new List<OrderItem>
        {
            new() { ProductName = "Item", Price = (decimal)price, Quantity = qty },
        };

        var order = _service.CreateOrder("cust-1", items);

        Assert.AreEqual((decimal)expectedTotal, order.Total);
    }

    #endregion
}

